47	  std::string out;
48	  for (size_t i = 0; i < allowed.size(); ++i) {
49	    if (i > 0) out += (i + 1 == allowed.size()) ? " or " : ", ";
50	    out += MemorySpaceToString(allowed[i]);
51	  }
52	  return out;
53	}
54	
55	/// Reject an operand whose explicit memory space no pass can legalize.
56	///
57	/// Three states, three outcomes:
58	///
59	///  * **unset** — always legal. `nullopt` is the IR's "not decided yet", and
60	///    `InferTileMemorySpace` (pass 17) places the tile from consumer demand.
61	///    The `TileMemoryInferred` verifier checks the outcome afterwards.
62	///  * **set and allowed** — legal, nothing to do.
63	///  * **set, not allowed, but reachable by a `tile.move`** — also legal here.
64	///    Pass 17's MoveCollector inserts the move. This is the ordinary case for
65	///    `tile.matmul`'s Left/Right operands, reached from Mat by an MTE1 tmov.
66	///  * **set, not allowed, and unreachable** — a user error, reported here.
67	///
68	/// Only the last case is rejected, and the axis is *reachability in the ISA's
69	/// move graph*, not aliasing. In practice it fires on `Acc`: nothing writes L0C
70	/// except the MAD unit, so no target's SoC memory graph has an inbound
71	/// edge to `Acc` on any target. A tile that must be an accumulator therefore has
72	/// to be *created* in `Acc` — no copy can put it there afterwards. Without this
73	/// check the pass emits a `pto.tmov` into L0C that PTOAS rejects much later,
74	/// naming neither the tile nor the line that created it.
75	///
76	/// Deliberately narrow. `OpRegistry::Create` is not only the user-authoring
77	/// path: passes call it constantly on half-rewritten IR, where an operand may
78	/// still be the pre-legalization value (a GM tensor awaiting its `tile.load`, an
79	/// operand a later phase will bridge). Rejecting every constraint violation here
80	/// would reject those transients. So this checks only what *no* later phase can
81	/// repair, whatever order they run in:
82	///
83	///  * A `DDR`-resident operand is skipped outright — GM values reach on-chip by
84	///    `tile.load`, a different mechanism from `tile.move`, and always available.
85	///  * Otherwise the operand is rejected only when the constraint set contains no
86	///    space that any target can move into from where the operand actually is.
87	///    Today that means exactly one thing: a constraint of `{Acc}`. Nothing writes
88	///    L0C but the MAD unit, so an accumulator must be *created* in `Acc`.
89	///
90	/// Everything else — a Vec operand needing Left, a Mat operand needing Vec — is
91	/// left alone here even when it is also unimplementable, because at construction
92	/// time we cannot tell a settled operand from a transient one. Those belong to
93	/// `InferTileMemorySpace`'s MoveCollector, which runs on settled IR and knows the
94	/// configured target's exact adjacency via `SoC::GetMemoryGraph()`.
95	void CheckOperandMemorySpaceReachable(const OpMemorySpaceSpec& spec, const std::string& op_name,
96	                                      const std::vector<ExprPtr>& args, const Span& span) {
97	  if (spec.input_constraints.empty()) return;
98	
99	  const size_t n = std::min(spec.input_constraints.size(), args.size());
100	  for (size_t idx = 0; idx < n; ++idx) {
101	    const auto& allowed = spec.input_constraints[idx];
102	    if (allowed.empty() || !args[idx]) continue;
103	
104	    auto tile_type = As<TileType>(args[idx]->GetType());
105	    if (!tile_type) continue;
106	    const auto space = tile_type->memory_space_;
107	    if (!space.has_value()) continue;          // unset: the compiler will place it
108	    if (*space == MemorySpace::DDR) continue;  // reached by tile.load, not tile.move
109	    if (std::find(allowed.begin(), allowed.end(), *space) != allowed.end()) continue;
110	
111	    // Reachable from ANY on-chip space, not just this operand's: that is what
112	    // distinguishes "this particular hop is missing" (leave it to pass 17) from
113	    // "this destination has no inbound edge at all" (unfixable, reject now).
114	    const bool destination_ever_reachable =
115	        std::any_of(allowed.begin(), allowed.end(), [](MemorySpace target) {
116	          for (MemorySpace from : {MemorySpace::Vec, MemorySpace::Mat, MemorySpace::Acc, MemorySpace::Left,
117	                                   MemorySpace::Right, MemorySpace::Bias}) {
118	            if (IsTileMoveEverSupported(from, target)) return true;
119	          }
120	          return false;
121	        });
122	    if (destination_ever_reachable) continue;
123	
124	    const std::string wanted = FormatAllowedSpaces(allowed);
125	    std::string msg = "The operator " + op_name + " requires argument " + std::to_string(idx) +
126	                      " to live in " + wanted + " memory, but it is in " + MemorySpaceToString(*space) +
127	                      " memory. No target has any data path into " + wanted +
128	                      " memory -- only the matrix unit writes it -- so the compiler " +
129	                      "cannot insert a copy to bridge them. The value has to be produced there " +
130	                      "in the first place: either by a matmul, or by an allocation that names " +
131	                      "the space (target_memory=pl.MemorySpace." + MemorySpaceToString(allowed[0]) +
132	                      "), or by an allocation left unset for the compiler to place.";
133	    if (allowed.size() == 1 && allowed[0] == MemorySpace::Acc) {
134	      // The common way to land here is a zero-initialized accumulator written as
135	      // `tile.full`, whose output space is fixed to UB and so can never be it.
136	      // Name the replacement, because there is no in-place rewrite of `tile.full`
137	      // that would work: `init_cond` removes the need to pre-zero at all.
138	      msg +=
139	          " Note that `tile.full` fills UB and cannot produce an accumulator. To start an"
140	          " accumulation from zero, drop the pre-zeroed tile and pass"
141	          " `init_cond=<true on the first step>` to the accumulating op instead -- it overwrites"
142	          " on that step rather than accumulating into it.";
143	    }
144	    throw ValueError(msg + LocationSuffix(span));
145	  }
146	}
147	
148	}  // namespace
149	
150	void ValidateKwargs(const std::vector<std::pair<std::string, std::any>>& kwargs,
151	                    const std::unordered_map<std::string, std::type_index>& allowed_kwargs,
152	                    const std::string& op_name) {
153	  for (const auto& [key, value] : kwargs) {
154	    auto it = allowed_kwargs.find(key);
155	    if (it == allowed_kwargs.end()) {
156	      throw ValueError("Unknown kwarg '" + key + "' for operator '" + op_name + "'");
157	    }
158	
159	    // For DataType, accept both DataType and int (since Python may pass as int for backward compatibility)
160	    if (it->second == std::type_index(typeid(DataType))) {
161	      std::type_index value_type(value.type());
162	      if (value_type != std::type_index(typeid(DataType)) && value_type != std::type_index(typeid(int))) {
163	        throw TypeError("Kwarg '" + key + "' for operator '" + op_name +
164	                        "' expects DataType or int, but got incompatible type");
165	      }
166	    } else if (it->second == std::type_index(typeid(MemorySpace))) {
167	      if (std::type_index(value.type()) != std::type_index(typeid(MemorySpace))) {
168	        throw TypeError("Kwarg '" + key + "' for operator '" + op_name +
169	                        "' expects MemorySpace, but got incompatible type");
170	      }
171	    } else if (it->second == std::type_index(typeid(TileLayout))) {
172	      if (std::type_index(value.type()) != std::type_index(typeid(TileLayout))) {
173	        throw TypeError("Kwarg '" + key + "' for operator '" + op_name +
174	                        "' expects TileLayout, but got incompatible type");
175	      }
176	    } else if (std::type_index(value.type()) != it->second) {
177	      throw TypeError("Kwarg '" + key + "' for operator '" + op_name + "' has incompatible type");
178	    }
179	  }
180	}
