187	OpRegistryEntry& OpRegistry::Register(const std::string& op_name) {
188	  // Check if operator is already registered
189	  CHECK(registry_.find(op_name) == registry_.end()) << "Operator '" + op_name + "' is already registered";
190	
191	  // Create and insert the entry into the registry
192	  auto result = registry_.emplace(op_name, OpRegistryEntry());
193	  auto& entry = result.first->second;
194	  entry.set_name(op_name);
195	
196	  // Create the operator instance with the operator name
197	  entry.op_ = std::make_shared<Op>(op_name);
198	
199	  return entry;
200	}
