237	
238	CallPtr OpRegistry::CreateImpl(const std::string& op_name, const std::vector<ExprPtr>& args,
239	                               const std::vector<std::pair<std::string, std::any>>& kwargs, Span span,
240	                               bool allow_internal) const {
241	  // Look up operator in registry
242	  auto it = registry_.find(op_name);
243	  if (it == registry_.end()) {
244	    std::string msg = "Operator '" + op_name + "' not found in registry";
245	    if (op_name.find('.') == std::string::npos) {
246	      msg +=
247	          ". This looks like a function name (GlobalVar), not a registered operator. "
248	          "Callers should check for GlobalVar before using OpRegistry::Create.";
249	    }
250	    throw ValueError(msg);
251	  }
252	
253	  const auto& entry = it->second;
254	  if (entry.IsInternalOnly() && !allow_internal) {
255	    throw ValueError("Operator '" + op_name +
256	                     "' is internal-only and cannot be created from user-facing op creation paths");
257	  }
258	
259	  // Get operator instance (shared definition)
260	  OpPtr op = entry.GetOp();
261	
262	  // Validate kwargs against allowed attributes (stored in Op)
263	  if (!kwargs.empty()) {
264	    const auto& allowed_kwargs = op->GetAttrs();
265	    if (!allowed_kwargs.empty()) {
266	      ValidateKwargs(kwargs, allowed_kwargs, op_name);
267	    }
268	  }
269	
270	  const auto& deduce_type_fn = entry.GetDeduceType();
271	
272	  // Deduce result type (pass args and kwargs separately)
273	  TypePtr result_type;
274	  try {
275	    result_type = deduce_type_fn(args, kwargs);
276	  } catch (const Error& e) {
277	    // Append the IR location but keep the concrete exception type and the stack trace
278	    // captured at the original throw. Flattening every PyPTO exception to ValueError
279	    // here erased the CHECK / INTERNAL_CHECK distinction for all op type deduction.
280	    e.RethrowWithMessage(std::string(e.what()) + LocationSuffix(span));
281	  } catch (const std::exception& e) {
282	    // Non-PyPTO exceptions (e.g. std::bad_any_cast from a wrong-typed kwarg) stay
283	    // ValueError: they are reachable from user input and carry no PyPTO trace to keep.
284	    throw ValueError(std::string(e.what()) + LocationSuffix(span));
285	  }
286	  INTERNAL_CHECK_SPAN(result_type, span) << "Type deduction failed for '" + op_name + "'";
287	
288	  // Apply OpMemorySpaceSpec to TileType results that lack memory_space.
289	  // This ensures the deduced type carries memory_space even when individual
290	  // type deduction functions omit it (fixes issue #553).
291	  //
292	  // Single-output ops: patch the result TileType directly.
293	  // Tuple-output ops (e.g. tile.gather_compare): patch each TileType element
294	  // that lacks a memory_space. Heterogeneous-output ops should set
295	  // memory_space_ inside f_deduce_type rather than relying on this fallback.
296	  const auto& mem_spec = entry.GetMemorySpec();
297	  if (mem_spec.has_value()) {
298	    CheckOperandMemorySpaceReachable(*mem_spec, op_name, args, span);
299	  }
300	  if (mem_spec.has_value() && mem_spec->deduce_output_memory) {
301	    auto resolve_memory_space = [&]() -> std::optional<MemorySpace> {
302	      auto resolved = mem_spec->deduce_output_memory(kwargs);
303	      if (resolved.has_value()) {
304	        return resolved;
305	      }
306	      // Inherit from first tile-typed input
307	      for (const auto& arg : args) {
308	        if (auto input_tile = As<TileType>(arg->GetType())) {
309	          if (input_tile->memory_space_.has_value()) {
310	            return input_tile->memory_space_;
311	          }
312	        }
313	      }
314	      return std::nullopt;
315	    };
316	    auto apply_memory_space = [](const TileTypePtr& tile_type, MemorySpace space) {
317	      return std::make_shared<TileType>(tile_type->shape_, tile_type->dtype_, tile_type->memref_,
318	                                        tile_type->tile_view_, space);
319	    };
320	
321	    if (auto tile_type = As<TileType>(result_type)) {
322	      // Single-output case: result is a TileType.
323	      if (!tile_type->memory_space_.has_value()) {
324	        if (auto space = resolve_memory_space(); space.has_value()) {
325	          result_type = apply_memory_space(tile_type, *space);
326	        }
327	      }
328	    } else if (auto tuple_type = As<TupleType>(result_type)) {
329	      // Multi-output case: result is a TupleType. Patch every TileType
330	      // element that is missing a memory_space.
331	      bool any_missing = false;
332	      for (const auto& elem_ty : tuple_type->types_) {
333	        if (auto elem_tile = As<TileType>(elem_ty); elem_tile && !elem_tile->memory_space_.has_value()) {
334	          any_missing = true;
335	          break;
336	        }
337	      }
338	      if (any_missing) {
339	        if (auto space = resolve_memory_space(); space.has_value()) {
340	          std::vector<TypePtr> new_elems;
341	          new_elems.reserve(tuple_type->types_.size());
342	          for (const auto& elem_ty : tuple_type->types_) {
343	            if (auto elem_tile = As<TileType>(elem_ty); elem_tile && !elem_tile->memory_space_.has_value()) {
344	              new_elems.push_back(apply_memory_space(elem_tile, *space));
345	            } else {
346	              new_elems.push_back(elem_ty);
347	            }
348	          }
349	          result_type = std::make_shared<TupleType>(std::move(new_elems));
350	        }
351	      }
352	    }
353	  }
354	
355	  // Create Call with deduced type
356	  return std::make_shared<Call>(op, args, kwargs, result_type, std::move(span));
357	}
