365	OpPtr OpRegistry::GetOp(const std::string& op_name) const {
366	  auto it = registry_.find(op_name);
367	  CHECK(it != registry_.end()) << "Operator '" + op_name + "' not found in registry";
368	  return it->second.GetOp();
369	}
370	
371	void OpRegistry::ValidateTileOps() const {
372	  std::vector<std::string> missing;
373	  for (const auto& [name, entry] : registry_) {
374	    if (name.rfind("tile.", 0) != 0) continue;
375	    if (entry.GetMemorySpec().has_value()) continue;
376	    missing.push_back(name);
377	  }
378	  if (!missing.empty()) {
379	    std::sort(missing.begin(), missing.end());
380	    std::string msg =
381	        "The following tile ops are missing a memory spec "
382	        "(add set_output_memory/set_input_memory or no_memory_spec()):";
383	    for (const auto& name : missing) {
384	      msg += "\n  - " + name;
385	    }
386	    throw ValueError(msg);
387	  }
388	}
389	
390	void OpRegistry::ValidateArgEffects() const {
391	  std::vector<std::string> unclassified;
392	  std::vector<std::string> channel_without_write;
393	  for (const auto& [name, entry] : registry_) {
394	    // A write channel describes *how* an operator writes, so declaring one
395	    // while writing nothing is incoherent — and it is the shape that hides a
396	    // missing classification, since `set_write_channel()` creates the effect
397	    // spec as a side effect and would otherwise make the operator look
398	    // classified.
399	    if (entry.GetWriteChannel().has_value() && !entry.WritesAnyArg()) {
400	      channel_without_write.push_back(name);
401	    }
402	    const auto& spec = entry.GetMemorySpec();
403	    if (!spec.has_value() || !spec->output_reuses_input_arg.has_value()) continue;
404	    const size_t reused = *spec->output_reuses_input_arg;
405	    // Ask about the reused argument specifically. A registration that named a
406	    // different argument still leaves this one defaulting to `Read`, and the
407	    // whole point of the gate is that such a default is a decision nobody made.
408	    if (entry.HasDeclaredArgEffect(reused)) continue;
409	    unclassified.push_back(name + " (in-place on argument " + std::to_string(reused) + ")");
410	  }
411	  if (!channel_without_write.empty()) {
412	    std::sort(channel_without_write.begin(), channel_without_write.end());
413	    std::string msg =
414	        "The following ops declare a write channel but write through no argument. A channel says "
415	        "how an op writes, so one without a write is either a stray declaration or a missing "
416	        "one — add the .set_arg_effect(<index>, ...) that was meant to accompany it, or drop the "
417	        ".set_write_channel(...):";
418	    for (const auto& name : channel_without_write) {
419	      msg += "\n  - " + name;
420	    }
421	    throw ValueError(msg);
422	  }
423	  if (!unclassified.empty()) {
424	    std::sort(unclassified.begin(), unclassified.end());
425	    std::string msg =
426	        "The following ops update an argument in place but never declared what they do to it. "
427	        "Direction inference reads an undeclared operator as a pure consumer, so the write is "
428	        "silently dropped. Add .set_arg_effect(<index>, ArgEffect::Write) — ArgEffect::ReadWrite "
429	        "when the op accumulates into the slot — or .no_arg_writes() when the slot is metadata "
430	        "rather than data:";
431	    for (const auto& name : unclassified) {
432	      msg += "\n  - " + name;
433	    }
434	    throw ValueError(msg);
435	  }
436	}
