    "create_op_call",
    [](const std::string& op_name, const std::vector<ExprPtr>& args, const nb::dict& kwargs_dict,
       const Span& span) {
      // Convert Python dict to C++ vector<pair<string, any>> to preserve order
      auto kwargs = ConvertKwargsDict(kwargs_dict);
